WHERE tenant_id=#{tenantId}
AND status='ACTIVE'


        AND knowledge_base_id=#{parentId}
        AND document_id=#{parentId}
        AND document_version_id=#{parentId}




        AND name LIKE CONCAT('%',#{search},'%')
        AND document_name LIKE CONCAT('%',#{search},'%')
        AND version LIKE CONCAT('%',#{search},'%')
        AND status LIKE CONCAT('%',#{search},'%')
        AND content LIKE CONCAT('%',#{search},'%')

mapper.update:
UPDATE  SET
${column}=#{value}
WHERE id=#{id} AND tenant_id=#{tenantId}

UPDATE ai_knowledge_document_version v SET index_status='PENDING',error_message=NULL
WHERE id=#{versionId} AND tenant_id=#{tenantId}
  AND NOT EXISTS (SELECT 1 FROM ai_knowledge_ingestion_job j WHERE j.document_version_id=v.id AND j.tenant_id=v.tenant_id AND CAST(j.index_revision AS UNSIGNED)>#{revision})
